.cs-command-center {
  position: fixed;
  bottom: 18px;
  right: 18px;
  width: 340px;
  max-height: 520px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-muted);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.18);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 9999;
}

.cs-command-center header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  background: linear-gradient(135deg, rgba(81, 52, 255, 0.14), rgba(0, 205, 172, 0.12));
  border-bottom: 1px solid var(--border-muted);
}

.cs-command-center h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}

.cs-command-center .pill {
  background: var(--bg-alt);
  padding: 6px 10px;
  border-radius: 12px;
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.cs-command-center .search-box {
  display: flex;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-muted);
}

.cs-command-center .search-box input {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid var(--border-muted);
  border-radius: 10px;
  background: var(--bg);
  color: var(--text-primary);
}

.cs-command-center .actions,
.cs-command-center .stats {
  padding: 10px 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.cs-command-center button {
  padding: 10px;
  background: var(--bg-alt);
  border: 1px solid var(--border-muted);
  color: var(--text-primary);
  border-radius: 10px;
  text-align: left;
  cursor: pointer;
  transition: background 0.12s ease, transform 0.12s ease;
}

.cs-command-center button:hover {
  background: var(--bg-hover);
  transform: translateY(-1px);
}

.cs-command-center .stat-card {
  background: linear-gradient(135deg, rgba(81, 52, 255, 0.1), rgba(0, 205, 172, 0.1));
  border: 1px solid var(--border-muted);
  border-radius: 10px;
  padding: 10px;
  font-size: 0.9rem;
}

.cs-command-center footer {
  padding: 10px 14px;
  border-top: 1px solid var(--border-muted);
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.cs-command-center .progress {
  height: 6px;
  border-radius: 999px;
  background: var(--bg-alt);
  overflow: hidden;
  margin-top: 6px;
}

.cs-command-center .progress > span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #7c3aed, #00cdaa);
}

.cs-command-center .badge-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 8px;
}

.cs-command-center .badge {
  padding: 4px 8px;
  border-radius: 10px;
  background: var(--bg-alt);
  border: 1px solid var(--border-muted);
  font-size: 0.75rem;
}

