(function() {
  'use strict';
  const api = window.CardSpoke.utils;
  const state = {
    open: true,
    stats: { cards: 0, tags: 0, completed: 0 },
    progress: 0,
    intervalId: null,
  };

  function createEl(tag, className, text) {
    const el = document.createElement(tag);
    if (className) el.className = className;
    if (text) el.textContent = text;
    return el;
  }

  function buildUI() {
    const panel = createEl('div', 'cs-command-center');
    const header = createEl('header');
    header.appendChild(createEl('h3', null, 'Command Center'));
    header.appendChild(createEl('span', 'pill', 'Ctrl/Cmd + Shift + P'));

    const searchBox = createEl('div', 'search-box');
    const searchInput = createEl('input');
    searchInput.placeholder = 'Search cards, tags, or shortcuts';

    const searchButton = createEl('button', null, 'Run');
    searchButton.addEventListener('click', () => runSearch(searchInput.value));
    searchInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') runSearch(searchInput.value);
    });
    searchBox.append(searchInput, searchButton);

    const actions = createEl('div', 'actions');
    const quickActions = [
      { label: 'New Card', handler: () => api.createCard('New Card', 'Describe next steps...') },
      { label: 'Flag Sprint', handler: () => api.addTagToAll('sprint:current') },
      { label: 'Toggle Focus Mode', handler: toggleFocusMode },
      { label: 'Daily Summary', handler: showDailySummary },
      { label: 'Bookmark Board', handler: bookmarkBoard },
      { label: 'Open Playground', handler: () => api.navigateTo('playground') },
    ];
    quickActions.forEach(({ label, handler }) => {
      const btn = createEl('button', null, label);
      btn.addEventListener('click', handler);
      actions.appendChild(btn);
    });

    const stats = createEl('div', 'stats');
    ['Cards', 'Tags', 'Completed'].forEach((title, idx) => {
      const card = createEl('div', 'stat-card');
      card.appendChild(createEl('div', null, title));
      const value = createEl('strong', null, '0');
      value.dataset.key = ['cards', 'tags', 'completed'][idx];
      card.appendChild(value);
      stats.appendChild(card);
    });

    const footer = createEl('footer');
    const streak = createEl('div', null, 'Focus streak');
    const progress = createEl('div', 'progress');
    const bar = createEl('span');
    progress.appendChild(bar);
    const badgeRow = createEl('div', 'badge-row');
    ['Auto-save', 'Focus Timer', 'Quick Actions', 'Playground'].forEach(label => {
      badgeRow.appendChild(createEl('span', 'badge', label));
    });
    footer.append(streak, progress, badgeRow);

    panel.append(header, searchBox, actions, stats, footer);
    document.body.appendChild(panel);

    state.elements = { panel, searchInput, bar, statsContainer: stats };
    updateStats();
    startProgressLoop();
  }

  function runSearch(query) {
    const trimmed = (query || '').trim();
    if (!trimmed) {
      api.showToast('Type something to search', 'warning');
      return;
    }
    const results = api.searchCards(trimmed).slice(0, 5);
    if (!results.length) {
      api.showToast('No results found', 'info');
      return;
    }
    const titles = results.map(r => r.title || 'Untitled').join(' • ');
    api.showToast(`Top results: ${titles}`, 'success');
  }

  function toggleFocusMode() {
    document.body.classList.toggle('cs-focus-mode');
    api.showToast('Focus mode toggled', 'info');
  }

  function showDailySummary() {
    const summaries = [
      '2 cards updated, 1 new tag added',
      '5 cards completed, 3 cards deferred',
      'Upcoming: Planning session at 3 PM',
    ];
    const summary = summaries[Math.floor(Math.random() * summaries.length)];
    api.showToast(`Daily summary: ${summary}`, 'success');
  }

  function bookmarkBoard() {
    try {
      const board = api.getCurrentBoard();
      if (!board) throw new Error('No active board');
      api.saveSetting('bookmarks', { ...(api.loadSetting('bookmarks') || {}), [board.id]: Date.now() });
      api.showToast(`Bookmarked ${board.name}`, 'success');
    } catch (err) {
      api.showToast(err.message || 'Could not bookmark board', 'error');
    }
  }

  function updateStats() {
    try {
      const cards = api.searchCards('');
      const tags = api.listTags ? api.listTags() : [];
      const completed = cards.filter(c => c.status === 'done' || c.tags?.includes('done')).length;
      state.stats = { cards: cards.length, tags: tags.length, completed };
    } catch (err) {
      state.stats = { cards: 0, tags: 0, completed: 0 };
    }
    document.querySelectorAll('[data-key]').forEach(el => {
      const key = el.dataset.key;
      el.textContent = state.stats[key] ?? 0;
    });
  }

  function startProgressLoop() {
    state.progress = 0;
    if (state.intervalId) clearInterval(state.intervalId);
    state.intervalId = setInterval(() => {
      state.progress = (state.progress + 7) % 100;
      if (state.elements?.bar) {
        state.elements.bar.style.width = state.progress + '%';
      }
      if (state.progress === 0) {
        updateStats();
      }
    }, 1000);
  }

  function handleShortcut(e) {
    const mod = navigator.platform.includes('Mac') ? e.metaKey : e.ctrlKey;
    if (mod && e.shiftKey && e.key.toLowerCase() === 'p') {
      e.preventDefault();
      if (!state.elements?.panel) buildUI();
      state.open = !state.open;
      state.elements.panel.style.display = state.open ? 'flex' : 'none';
      if (state.open) state.elements.searchInput?.focus();
    }
  }

  window.addEventListener('keydown', handleShortcut);
  api.showToast('Command Center Plugin loaded', 'success');
})();

