(function() {
  'use strict';
  const api = window.CardSpoke.utils;
  const ribbon = document.createElement('div');
  ribbon.className = 'cs-nav-ribbon';
  const destinations = [
    { label: 'Boards', target: 'boards', hotkey: '1' },
    { label: 'Backlog', target: 'backlog', hotkey: '2' },
    { label: 'Focus', target: 'focus', hotkey: '3' },
    { label: 'Playground', target: 'playground', hotkey: '4' }
  ];
  destinations.forEach(dest => {
    const btn = document.createElement('button');
    btn.textContent = `${dest.label} (${dest.hotkey})`;
    btn.addEventListener('click', () => api.navigateTo(dest.target));
    ribbon.appendChild(btn);
  });
  document.body.appendChild(ribbon);

  window.addEventListener('keydown', (e) => {
    const mod = navigator.platform.includes('Mac') ? e.metaKey : e.ctrlKey;
    if (!mod) return;
    const dest = destinations.find(d => d.hotkey === e.key);
    if (dest) {
      e.preventDefault();
      api.navigateTo(dest.target);
      api.showToast(`Jumped to ${dest.label}`, 'success');
    }
  });
})();

