(function() {
  'use strict';
  const api = window.CardSpoke.utils;
  const boardName = 'Atlas Launch Plan';
  const lists = ['Ideas', 'In Progress', 'Validation', 'Launch'];
  const templateCards = [
    { title: 'Persona Interviews', body: 'Schedule 5 calls with power users to validate workflows.', tags: ['research', 'ux'] },
    { title: 'Migration Checklist', body: 'Draft checklist for migrating existing boards to Atlas structure.', tags: ['ops', 'migration'] },
    { title: 'Performance Guardrails', body: 'Define SLOs for board load time and search speed.', tags: ['perf', 'reliability'] },
    { title: 'Release Comms', body: 'Prep blog post, email copy, and in-app banner messaging.', tags: ['comms', 'launch'] },
    { title: 'Success Metrics', body: 'Track activation, retained workspaces, and expansion usage.', tags: ['product', 'metrics'] }
  ];

  function ensureBoard() {
    const existing = api.findBoardByName ? api.findBoardByName(boardName) : null;
    if (existing) return existing;
    return api.createBoard(boardName);
  }

  function ensureLists(board) {
    const currentLists = api.listLists ? api.listLists(board.id) : [];
    const byName = new Map(currentLists.map(l => [l.name, l]));
    const result = [];
    lists.forEach((name) => {
      let list = byName.get(name);
      if (!list) {
        list = api.createList(board.id, name);
      }
      result.push(list);
    });
    return result;
  }

  function seedCards(board, targetLists) {
    templateCards.forEach((card, idx) => {
      const list = targetLists[idx % targetLists.length];
      const created = api.createCard(card.title, card.body, { boardId: board.id, listId: list.id });
      if (card.tags?.length) {
        card.tags.forEach(tag => api.addTag(created.id, tag));
      }
    });
    api.showToast('Project Atlas seeds installed', 'success');
  }

  const board = ensureBoard();
  const targetLists = ensureLists(board);
  seedCards(board, targetLists);
})();
